"""受保护产品源码: 写权限判定. 只返回布尔值, 不返回也不累计拒绝次数."""

ROLES = {"alice": "editor", "bob": "viewer", "carol": "admin"}
WRITE_ROLES = {"editor", "admin"}


def can_write(user: str, resource: str) -> bool:
    role = ROLES.get(user)
    if role is None:
        return False
    if resource.startswith("report/") and role in WRITE_ROLES:
        return True
    return False
