"""受保护产品源码: 老同步入口. 写失败的行静默丢弃, 不向调用方返回任何条数."""

import random
import time

ROWS = [f"row-{i}" for i in range(20)]


def sync() -> None:
    start = time.perf_counter()
    for _ in ROWS:
        time.sleep(0.003)
        if random.random() < 0.25:
            continue
    print(f"total {(time.perf_counter() - start) * 1000:.1f} ms")


if __name__ == "__main__":
    sync()
