"""受保护产品源码: 写出端. 没有故障注入接口, 降级只由请求内容决定."""


def write_row(row: dict) -> dict:
    if row.get("skipped"):
        return {"written": 0, "skipped": 1}
    return {"written": 1, "skipped": 0}
